import React, { useState } from 'react';
import { Steps } from '@salutejs/sdds-finai';
export function App() {
    const [items, setItems] = useState([{
        indicator: 1,
        title: 'Шаг 1',
        status: 'active',
    }, {
        indicator: 2,
        title: 'Шаг 2',
        status: 'inactive',
    }, {
        indicator: 3,
        title: 'Шаг 3',
        status: 'inactive',
    }]);
    const onChange = (item, index, prevIndex) => {
        if (prevIndex !== undefined) {
            items[prevIndex].status = 'completed';
        }
        items[index].status = 'active';
        setItems([...items]);
    };
    return (
        <section>
            <Steps items={items} onChange={onChange} />
        </section>
    );
}

